#include <linux/personality.h>
#include <linux/version.h>
#include <string.h>
#include <asm/uaccess.h>

int modify_version_string(char __user *release, size_t len) {
    char version_buf[32];
    int version_len;
    unsigned int version = LINUX_VERSION_CODE;

    if (personality(current->personality) & UNAME26) {
        if (version >= KERNEL_VERSION(3, 0, 0)) {
            version_len = snprintf(version_buf, sizeof(version_buf), "Linux 2.6.%u", version - KERNEL_VERSION(3, 0, 0));
        } else {
            version_len = snprintf(version_buf, sizeof(version_buf), "Linux 2.6.%u", version);
        }
    } else {
        version_len = snprintf(version_buf, sizeof(version_buf), "Linux %u.%u.%u",
                               KERNEL_VERSION_MAJOR, KERNEL_VERSION_MINOR, KERNEL_VERSION_PATCHLEVEL);
    }

    if (version_len < 0 || version_len >= (int)sizeof(version_buf)) {
        return -EINVAL;
    }

    if (len < version_len + 1) {
        return -ENAMETOOLONG;
    }

    if (copy_to_user(release, version_buf, version_len + 1)) {
        return -EFAULT;
    }

    return version_len + 1;
}

#include <linux/personality.h>
#include <linux/version.h>
#include <linux/uaccess.h>
#include <linux/limits.h>

int construct_compat_uname(char __user *release, size_t len) {
    int ret = 0;
    char compat_release[32] = "Linux 2.6.";

    if (personality(current->personality) & (UNAME26 | UNAME32)) {
        unsigned int ver = LINUX_VERSION_CODE;

        if (ver < LINUX_VERSION(2, 6, 0)) {
            return -EINVAL;
        }

        // Compute the appropriate "x" in 2.6.x
        unsigned int major = (ver - LINUX_VERSION(2, 6, 0)) / 1000000;
        unsigned int minor = ((ver - LINUX_VERSION(2, 6, 0)) % 1000000) / 1000;
        unsigned int patch = (ver - LINUX_VERSION(2, 6, 0)) % 1000;

        int total_len = snprintf(compat_release + strlen(compat_release), sizeof(compat_release) - strlen(compat_release),
                                 "%u.%u.%u", major, minor, patch);

        if (total_len < 0)
            return total_len;

        if (len < total_len) {
            return -ENAMETOOLONG;
        }

        if (copy_to_user(release, compat_release, total_len)) {
            return -EFAULT;
        }

        ret = total_len;
    }

    return ret;
}

#include <linux/personality.h>
#include <linux/unistd.h>
