#include <asm/uaccess.h>

int format_uname_26(char __user *release, size_t len) {
    char buffer[32];
    int version = LINUX_VERSION_CODE;
    int major = 2, minor = 6, patch;

    if (len == 0)
        return 0;

    if (current->personality & UNAME26_FMT) {
        patch = (version >> 16) & 0xFF;
        if (patch > UCHAR_MAX)
            patch = UCHAR_MAX;
        snprintf(buffer, sizeof(buffer), "Linux 2.6.%d", patch);
    } else {
        snprintf(buffer, sizeof(buffer), "Linux %d.%d.%d", 
                 (version >> 16) & 0xFF,
                 (version >> 8) & 0xFF,
                 version & 0xFF);
    }

    strncat(buffer, "\n", 1);

    if (strlen(buffer) >= len)
        return -ENAMETOOLONG;

    if (copy_to_user(release, buffer, strlen(buffer)))
        return -EFAULT;

    return strlen(buffer);
}

#include <string.h>
#include <linux/personality.h>
#include <linux/unistd.h>
#include <linux/version.h>
#include <linux/uaccess.h>

int modify_linux_version_string(char __user *release, size_t len) {
    unsigned long personality = personality(current->personality);
    char version_string[27];
    int version_code = LINUX_VERSION_CODE;
    int major = 2;
    int minor = 6;
    int patch = version_code / 1000;
    int ret;

    if (personality & (PER_LINUX | PER_LINUX_32BIT)) {
        if (version_code >= KERNEL_VERSION(3, 0, 0)) {
            patch = version_code / 1000;
        }

        snprintf(version_string, sizeof(version_string), "Linux 2.6.%d", patch);
        ret = strnlen(version_string, sizeof(version_string));
        if (ret > 0 && copy_to_user(release, version_string, ret))
            return -EFAULT;
        return ret;
    }

    return -EPERM;
}

#include <linux/personality.h>
#include <linux/version.h>
#include <string.h>
#include <unistd.h>
#include <limits.h>

int modify_version_string(char __user *release, size_t len) {
    char version_str[27];
    int version = LINUX_VERSION_CODE;
    int major = 2;
    int minor = 6;
    int patch = (version - KERNEL_VERSION(major, minor, 0)) / 1000;

    if (personality(PER_LINUX) == 0) {
        return -EPERM;
    }

    if (patch < 0) {
        return -EINVAL;
    }

    snprintf(version_str, sizeof(version_str), "Linux 2.%d.%d", minor, patch);

    if (len < strlen(version_str)) {
        return -ENOMEM;
    }

    if (copy_to_user(release, version_str, strlen(version_str) + 1)) {
        return -EFAULT;
    }

    return strlen(version_str) + 1;
}
